   Protection guard=new Protection(c);PackageManager pm=c.getPackageManager();check(guard.reason(pm.getApplicationInfo(c.getPackageName(),0))!=null,"Self protection enforced");check(guard.reason(pm.getApplicationInfo("com.android.settings",0))!=null,"Settings protected");check(guard.reason(pm.getApplicationInfo("com.android.providers.settings",0))!=null,"Settings provider protected");check(guard.reason(pm.getApplicationInfo(A,0))==null&&guard.reason(pm.getApplicationInfo(B,0))==null,"Ordinary user apps remain controllable");
   int guarded=0;for(ApplicationInfo app:pm.getInstalledApplications(0)){boolean system=(app.flags&(ApplicationInfo.FLAG_SYSTEM|ApplicationInfo.FLAG_UPDATED_SYSTEM_APP))!=0;if(system&&pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setPackage(app.packageName),0).isEmpty()){check(guard.reason(app)!=null,"Non-launchable system package protected: "+app.packageName);guarded++;}}check(guarded>0,"System safeguard inventory was checked");
   boolean blocked=false;try{engine.setEnabled(c.getPackageName(),false);}catch(SecurityException expected){blocked=true;}check(blocked,"Privileged engine rejects self-disable");
