   setQuery("dev.raven.control.fixture");navigate("Disabled");onUi(()->{check(appSwitch(A)!=null&&appSwitch(B)!=null,"Both searched apps appear together in Disabled");});
   ActivityMonitor monitor=addMonitor(MainActivity.class.getName(),null,false);onUi(activity::recreate);Activity recreated=monitor.waitForActivityWithTimeout(8000);removeMonitor(monitor);check(recreated!=null,"Activity recreates");activity=recreated;waitText("AYN root connected");check(!new ControlEngine(c).isEnabled(A)&&!new ControlEngine(c).isEnabled(B),"Both app states persist through activity recreation");
   setQuery("Raven Control Test App");onUi(()->appSwitch(A).performClick());waitState(A,true);verifyConfirmation("Enabled");click("Close");check(!engine.isEnabled(B),"Restoring first app leaves second disabled");setQuery(B);onUi(()->appSwitch(B).performClick());waitState(B,true);verifyConfirmation("Enabled");click("Close");setQuery("");navigate("Enabled");
   for(String name:new String[]{A,B})check(AynRoot.execute("cat /data/user/0/"+name+"/files/keep.txt").equals("raven-control-data-preserved"),"Private data preserved after sequential search: "+name);
   overflow();check(node("Settings")!=null&&node("About")!=null&&node("Help")==null,"Menu has Settings and About, no Help");click("Settings");waitText("Appearance");
