   click("Accent color");check(node("Other Raven apps")!=null&&node("Other colors")!=null,"Preset groups are labelled");String[] presetNames={"Raven Backup #64C895","Raven System Control #FF8000","Raven Gamepad #0070CC","Purple #8000FF","Yellow #FFFF00","White #FFFFFF"};for(String name:presetNames)check(node("Use "+name)!=null,"Preset dot exists: "+name);check(findContains(getUiAutomation().getRootInActiveWindow(),"Hue and saturation color wheel")!=null,"Color wheel is available");check(node("Red channel")!=null&&node("Green channel")!=null&&node("Blue channel")!=null,"RGB sliders available");
